package com.amdocs.telecom;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import com.amdocs.telecom.security.*;import com.amdocs.telecom.service.*;import com.amdocs.telecom.model.Types.SLAStatus;import java.sql.Timestamp;public class CoreTest{@Test void passwordHash(){String h=PasswordUtil.hash("secret");assertTrue(PasswordUtil.verify("secret",h));assertFalse(PasswordUtil.verify("wrong",h));}@Test void captchaOneTime(){CaptchaGenerator c=new CaptchaGenerator();String[]v=c.create();assertTrue(c.verify(v[0],v[1]));assertFalse(c.verify(v[0],v[1]));}@Test void sla(){SLAService s=new SLAService();assertEquals(SLAStatus.BREACHED,s.status(new Timestamp(System.currentTimeMillis()-1000)));assertEquals(SLAStatus.AT_RISK,s.status(new Timestamp(System.currentTimeMillis()+10*60*1000)));}}
